window.CherriftStorage = {
  key: "cherrift_save_v025_polish",
  defaults() {
    return {
      coins: 0,
      keys: 3,
      selectedSkin: "cherry_default",
      unlockedSkins: ["cherry_default", "fairy_cherry"],
      inventory: [],
      equipped: {},
      best: { time:0, kills:0 },
      settings: { volume:60, touchMode:true, fpsLimit:60 }
    };
  },
  load() {
    try {
      const raw = localStorage.getItem(this.key);
      const data = raw ? JSON.parse(raw) : {};
      const d = this.defaults();
      const save = { ...d, ...data };
      save.best = { ...d.best, ...(data.best || {}) };
      save.settings = { ...d.settings, ...(data.settings || {}) };
      save.settings.fpsLimit = [30, 60].includes(+save.settings.fpsLimit) ? +save.settings.fpsLimit : 60;
      save.equipped = data.equipped || {};
      save.inventory = Array.isArray(data.inventory) ? data.inventory : [];
      save.unlockedSkins = Array.isArray(data.unlockedSkins) ? data.unlockedSkins : [...d.unlockedSkins];
      for (const id of d.unlockedSkins) if (!save.unlockedSkins.includes(id)) save.unlockedSkins.push(id);
      if (!CHERRIFT_DATA.skins.some(s => s.id === save.selectedSkin)) save.selectedSkin = "cherry_default";
      return save;
    } catch(e) {
      return this.defaults();
    }
  },
  save(data) {
    localStorage.setItem(this.key, JSON.stringify(data));
  }
};
/* ===== END src/storage.js ===== */


/* ===== BEGIN src/input.js ===== */
class CherriftInput {
  constructor() {
    this.keys = new Set();
    this.skillQueued = false;
    this.touchMode = true;
    this.pointerId = null;
    this.pointerStart = { x:0, y:0 };
    this.pointerNow = { x:0, y:0 };
    this.pointerActive = false;

    window.addEventListener("keydown", e => {
      const k = e.key.toLowerCase();
      this.keys.add(k);
      const playing = document.body.classList.contains("is-playing") &&
        (!window.UI?.game || window.UI.game.mode === "playing");
      if (playing && [" ", "spacebar", "e", "shift"].includes(k)) {
        this.skillQueued = true;
        e.preventDefault();
      }
    });

    window.addEventListener("keyup", e => this.keys.delete(e.key.toLowerCase()));

    const skill = document.getElementById("skill");
    if (skill) {
      skill.addEventListener("pointerdown", e => {
        this.skillQueued = true;
        e.preventDefault();
        e.stopPropagation();
      });
    }

    window.addEventListener("pointerdown", e => {
      if (!this.shouldStartMove(e)) return;
      this.pointerId = e.pointerId;
      this.pointerActive = true;
      this.pointerStart = { x:e.clientX, y:e.clientY };
      this.pointerNow = { x:e.clientX, y:e.clientY };
    }, { passive:true });

    window.addEventListener("pointermove", e => {
      if (!this.pointerActive || e.pointerId !== this.pointerId) return;
      this.pointerNow = { x:e.clientX, y:e.clientY };
    }, { passive:true });

    const end = e => {
      if (e.pointerId !== this.pointerId) return;
      this.pointerActive = false;
      this.pointerId = null;
    };
    window.addEventListener("pointerup", end, { passive:true });
    window.addEventListener("pointercancel", end, { passive:true });

    const reset = () => {
      this.keys.clear();
      this.skillQueued = false;
      this.pointerActive = false;
      this.pointerId = null;
    };
    window.addEventListener("blur", reset);
    document.addEventListener("visibilitychange", () => {
      if (document.hidden) reset();
    });
  }

  shouldStartMove(e) {
    const inGame = document.body.classList.contains("is-playing") &&
      (!window.UI?.game || window.UI.game.mode === "playing");
    if (!inGame || !this.touchMode) return false;
    if (e.target.closest("button,input,.modal,.panel,.menu-screen")) return false;
    return true;
  }

  getMoveVector() {
    let x = 0;
    let y = 0;
    if (this.keys.has("a") || this.keys.has("arrowleft")) x -= 1;
    if (this.keys.has("d") || this.keys.has("arrowright")) x += 1;
    if (this.keys.has("w") || this.keys.has("arrowup")) y -= 1;
    if (this.keys.has("s") || this.keys.has("arrowdown")) y += 1;

    if (this.pointerActive) {
      const dx = this.pointerNow.x - this.pointerStart.x;
      const dy = this.pointerNow.y - this.pointerStart.y;
      const len = Math.hypot(dx, dy);
      if (len > 8) {
        x += dx / Math.max(60, len);
        y += dy / Math.max(60, len);
      }
    }

    const l = Math.hypot(x, y);
    if (l > 1) return { x:x/l, y:y/l };
    return { x, y };
  }

  consumeSkill() {
    if (!this.skillQueued) return false;
    this.skillQueued = false;
    return true;
  }
}
window.CherriftInput = CherriftInput;
/* ===== END src/input.js ===== */


/* ===== BEGIN src/game.js ===== */
class ImageAssets {
  constructor() {
    this.images = {};
    this.ready = false;
  }

  loadImage(key, src) {
    return new Promise(resolve => {
      const img = new Image();
      img.onload = () => { this.images[key] = img; resolve(true); };
      img.onerror = () => { console.warn("Missing image:", key, src); resolve(false); };
      img.src = src;
    });
  }

  async loadAll() {
    const c = CHERRIFT_CONFIG;
    const items = [];

    for (const [skinId, skin] of Object.entries(c.player.skins || {})) {
      for (const [stateName, state] of Object.entries(skin.states || {})) {
        for (const [dirName, src] of Object.entries(state.dirs || {})) {
          items.push([`player_${skinId}_${stateName}_${dirName}`, src]);
        }
      }
    }

    items.push(
      ["slime", c.slime.src],
      ["grass", c.map.grass],
      ["rockSmall", c.map.rockSmall],
      ["rockBig", c.map.rockBig],
      ["bush1", c.map.bush1],
      ["bush2", c.map.bush2],
      ["log", c.map.log],
      ["treeSmall", c.map.treeSmall],
      ["treeBig", c.map.treeBig],
      ["xpSmall", c.pickups.xpSmall],
      ["xpBig", c.pickups.xpBig],
      ["burst", c.effects.burst]
    );

    (c.effects.baseHit || []).forEach((src, i) => items.push([`baseHit${i + 1}`, src]));

    await Promise.all(items.map(([key, src]) => this.loadImage(key, src)));
    this.ready = true;
  }

  get(key) { return this.images[key] || null; }
}

class CherriftGame {
  constructor(canvas, input, save) {
    this.canvas = canvas;
    this.ctx = canvas.getContext("2d");
    this.input = input;
    this.save = save;
    this.mode = "menu";
    this.dpr = Math.max(1, Math.min(CHERRIFT_CONFIG.performance?.renderScaleMax || 1.5, window.devicePixelRatio || 1));
    this.w = 0;
    this.h = 0;
    this.last = performance.now();
    this.hitFx = 0;
    this.fpsLimit = this.save?.settings?.fpsLimit || CHERRIFT_CONFIG.performance?.defaultFpsLimit || 60;
    this.camera = { x:0, y:0 };
    this.t = 0;
    this.assets = new ImageAssets();
    this.assetReady = this.assets.loadAll();
    this.player = null;
    this.obstacles = [];
    this.enemies = [];
    this.bullets = [];
    this.pickups = [];
    this.effects = [];
    this.runCoins = 0;
    this.time = 0;
    this.kills = 0;
    this.spawnTimer = 0;
    this.resize();
    window.addEventListener("resize", () => this.resize());
    requestAnimationFrame(n => this.loop(n));
  }

  resize() {
    const r = this.canvas.getBoundingClientRect();
    this.w = Math.max(320, r.width || innerWidth);
    this.h = Math.max(240, r.height || innerHeight);
    this.canvas.width = Math.floor(this.w * this.dpr);
    this.canvas.height = Math.floor(this.h * this.dpr);
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.ctx.imageSmoothingEnabled = true;
    this.ctx.imageSmoothingQuality = "medium";
  }

  activeSkinData() {
    return CHERRIFT_DATA.skins.find(s => s.id === this.save.selectedSkin) || CHERRIFT_DATA.skins[0];
  }

  activeSkinConfig() {
    return CHERRIFT_CONFIG.player.skins[this.save.selectedSkin] || CHERRIFT_CONFIG.player.skins[CHERRIFT_CONFIG.player.defaultSkin];
  }

  async start() {
    await this.assetReady;
    const skin = this.activeSkinData();
    const gear = UI.totalGearStats(this.save);
    this.mode = "playing";
    document.body.classList.add("is-playing");
    this.runCoins = 0;
    this.time = 0;
    this.kills = 0;
    this.player = {
      x:0, y:0, r:18,
      hp:100 + (gear.maxHp || 0),
      maxHp:100 + (gear.maxHp || 0),
      speed:235 + (skin.stats.speed || 0) + (gear.moveSpeed || 0),
      damage:20 + (skin.stats.damage || 0) + (gear.damage || 0),
      fireInterval:Math.max(.18, .42 / (1 + (gear.attackSpeed || 0) / 100)),
      fireTimer:0,
      bulletSpeed:560,
      pickup:110 + (gear.pickup || 0),
      crit:.05 + (gear.crit || 0) / 100,
      critDamage:1.5 + (gear.critDamage || 0) / 100,
      armor:gear.armor || 0,
      regen:gear.regen || 0,
      level:1,
      xp:0,
      xpNext:18,
      skillTimer:0,
      skillCooldown:8,
      skillCastTimer:0,
      skillCastDuration:0,
      dashTimer:0,
      skin:skin.id,
      skillBuff:0,
      lastDir:"down",
      moving:false
    };
    this.enemies = [];
    this.bullets = [];
    this.pickups = [];
    this.effects = [];
    this.obstacles = this.generateMap();
    this.spawnTimer = 0;
    this.camera = { x:this.player.x, y:this.player.y };
    this.last = performance.now();
    UI.showGame();
  }

  generateMap() {
    const obs = [];
    const add = (kind, count, r, solid=true) => {
      for (let i=0; i<count; i++) {
        let x = 0, y = 0, ok = false;
        for (let t=0; t<90 && !ok; t++) {
          x = (Math.random() - .5) * 3600;
          y = (Math.random() - .5) * 3600;
          ok = Math.hypot(x, y) > 260 && obs.every(o => Math.hypot(o.x - x, o.y - y) > o.r + r + 38);
        }
        if (ok) obs.push({ kind, x, y, r, solid, phase:Math.random()*9 });
      }
    };
    add("treeBig", 8, 74, true);
    add("treeSmall", 12, 54, true);
    add("log", 14, 48, true);
    add("bush1", 14, 42, true);
    add("bush2", 13, 42, true);
    add("rockBig", 9, 38, true);
    add("rockSmall", 16, 30, true);
    add("flowers", 48, 18, false);
    return obs;
  }

  loop(now) {
    const fps = Math.max(30, Math.min(60, +(this.save?.settings?.fpsLimit || CHERRIFT_CONFIG.performance?.defaultFpsLimit || 60)));
    const minFrameMs = 1000 / fps;
    if (now - this.last < minFrameMs - 0.5) {
      requestAnimationFrame(n => this.loop(n));
      return;
    }

    const dt = Math.min(.05, (now - this.last) / 1000 || 0);
    this.last = now;
    this.t += dt;
    if (this.mode === "playing") this.update(dt);
    this.render();
    requestAnimationFrame(n => this.loop(n));
  }

  update(dt) {
    const p = this.player;
    if (!p) return;
    this.time += dt;
    p.fireTimer -= dt;
    p.skillTimer = Math.max(0, p.skillTimer - dt);
    p.skillBuff = Math.max(0, (p.skillBuff || 0) - dt);
    p.skillCastTimer = Math.max(0, (p.skillCastTimer || 0) - dt);
    p.invuln = Math.max(0, (p.invuln || 0) - dt);
    if (p.regen) p.hp = Math.min(p.maxHp, p.hp + p.regen * dt);

    const mv = this.input.getMoveVector();
    p.moving = !!(Math.abs(mv.x) > .04 || Math.abs(mv.y) > .04);
    if (p.moving) {
      p.lastDir = Math.abs(mv.x) > Math.abs(mv.y) ? (mv.x < 0 ? "left" : "right") : (mv.y < 0 ? "up" : "down");
    }
    this.movePlayer(mv, dt);

    if ((p.dashTimer || 0) > 0) {
      const old = p.speed;
      p.speed = p.dashSpeed || 760;
      this.movePlayer(p.dashDir || this.dirVector(p.lastDir), dt);
      p.speed = old;
      p.dashTimer = Math.max(0, p.dashTimer - dt);
    }

    if (this.input.consumeSkill()) this.skill();
    this.spawn(dt);
    this.autoFire();
    this.updateBullets(dt);
    this.updateEnemies(dt);
    this.updatePickups(dt);
    this.effects.forEach(e => e.t += dt);
    this.effects = this.effects.filter(e => e.t < e.life);
    this.camera.x += (p.x - this.camera.x) * Math.min(1, dt * 8);
    this.camera.y += (p.y - this.camera.y) * Math.min(1, dt * 8);
    UI.updateHUD(this);
    if (p.hp <= 0) this.gameOver();
  }

  dirVector(dir) {
    if (dir === "left") return { x:-1, y:0 };
    if (dir === "right") return { x:1, y:0 };
    if (dir === "up") return { x:0, y:-1 };
    return { x:0, y:1 };
  }

  movePlayer(mv, dt) {
    const p = this.player;
    const half = CHERRIFT_CONFIG.worldSize / 2 - 200;
    const tryMove = (dx, dy) => {
      if (!dx && !dy) return;
      p.x = Math.max(-half, Math.min(half, p.x + dx));
      p.y = Math.max(-half, Math.min(half, p.y + dy));
      if (this.hitObstacle()) {
        p.x -= dx;
        p.y -= dy;
      }
    };
    tryMove(mv.x * p.speed * dt, 0);
    tryMove(0, mv.y * p.speed * dt);
  }

  hitObstacle() {
    const p = this.player;
    return this.obstacles.some(o => o.solid && Math.hypot(p.x - o.x, p.y - o.y) < p.r + o.r * .62);
  }

  spawn(dt) {
    this.spawnTimer -= dt;
    const max = 22 + Math.floor(this.time / 10);
    if (this.spawnTimer <= 0 && this.enemies.length < max) {
      this.spawnTimer = Math.max(.24, 1.18 / (1 + this.time / 80));
      const count = 1 + Math.floor(this.time / 45);
      for (let i=0; i<count; i++) this.spawnEnemy();
    }
  }

  spawnEnemy() {
    const a = Math.random() * Math.PI * 2;
    const d = Math.max(this.w, this.h) * .68 + 120;
    const roll = Math.random();
    const type = roll < .62 ? "green" : roll < .86 ? "blue" : "pink";
    const spec = type === "green" ? { hp:40, speed:70, r:22, xp:3 } : type === "blue" ? { hp:65, speed:58, r:26, xp:5 } : { hp:34, speed:105, r:20, xp:4 };
    const scale = 1 + this.time / 120;
    this.enemies.push({
      type,
      x:this.player.x + Math.cos(a) * d,
      y:this.player.y + Math.sin(a) * d,
      r:spec.r,
      hp:spec.hp * scale,
      maxHp:spec.hp * scale,
      speed:spec.speed * (1 + this.time / 240),
      xp:spec.xp,
      hit:0,
      phase:Math.random()*9
    });
  }

  nearest(range=720) {
    let best = null;
    let bd = range;
    for (const e of this.enemies) {
      const d = Math.hypot(e.x - this.player.x, e.y - this.player.y);
      if (d < bd) { bd = d; best = e; }
    }
    return best;
  }

  autoFire() {
    const p = this.player;
    const interval = p.fireInterval * (p.skillBuff > 0 ? .55 : 1);
    if (p.fireTimer > 0) return;
    const e = this.nearest();
    if (!e) return;
    p.fireTimer = interval;
    const dx = e.x - p.x;
    const dy = e.y - p.y;
    const l = Math.hypot(dx, dy) || 1;
    const style = p.skin === "fairy_cherry" ? "petal" : "orb";
    this.bullets.push({ x:p.x, y:p.y - 10, vx:dx/l * p.bulletSpeed, vy:dy/l * p.bulletSpeed, r:style === "petal" ? 8 : 7, dmg:p.damage, life:1.45, style });
  }

  updateBullets(dt) {
    for (const b of this.bullets) { b.x += b.vx * dt; b.y += b.vy * dt; b.life -= dt; }
    for (const b of this.bullets) {
      if (b.dead) continue;
      for (const e of this.enemies) {
        if (Math.hypot(b.x - e.x, b.y - e.y) < b.r + e.r) {
          b.dead = true;
          let dmg = b.dmg;
          if (Math.random() < this.player.crit) { dmg *= this.player.critDamage; this.effects.push({ type:"crit", x:e.x, y:e.y, t:0, life:.35 }); }
          this.damageEnemy(e, dmg);
          this.hitFx = (this.hitFx % 3) + 1;
          this.effects.push({ type:"hit", x:b.x, y:b.y, t:0, life:.22, style:b.style, imgKey:`baseHit${this.hitFx}` });
          break;
        }
      }
    }
    this.bullets = this.bullets.filter(b => !b.dead && b.life > 0);
  }

  damageEnemy(e, dmg) {
    e.hp -= dmg;
    e.hit = .08;
    if (e.hp <= 0 && !e.dead) {
      e.dead = true;
      this.kills++;
      this.pickups.push({ type:"xp", x:e.x, y:e.y, value:e.xp, r:e.xp >= 5 ? 13 : 10 });
      if (Math.random() < .18) this.pickups.push({ type:"coin", x:e.x + (Math.random() - .5) * 24, y:e.y + (Math.random() - .5) * 24, value:1, r:8 });
      if (Math.random() < .018) this.pickups.push({ type:"key", x:e.x, y:e.y, value:1, r:11 });
      this.effects.push({ type:"death", x:e.x, y:e.y, t:0, life:.34 });
    }
  }

  updateEnemies(dt) {
    const p = this.player;
    for (const e of this.enemies) {
      if (e.dead) continue;
      e.hit = Math.max(0, e.hit - dt);
      const dx = p.x - e.x;
      const dy = p.y - e.y;
      const l = Math.hypot(dx, dy) || 1;
      e.x += dx/l * e.speed * dt;
      e.y += dy/l * e.speed * dt;
      if (l < e.r + p.r && !(p.invuln > 0)) {
        const raw = 16 * dt;
        p.hp -= Math.max(2 * dt, raw * (100 / (100 + p.armor * 4)));
      }
    }
    this.enemies = this.enemies.filter(e => !e.dead);
  }

  updatePickups(dt) {
    const p = this.player;
    for (const o of this.pickups) {
      const d = Math.hypot(o.x - p.x, o.y - p.y);
      if (d < p.pickup) {
        const sp = 260 + (1 - d / p.pickup) * 520;
        o.x += (p.x - o.x) / (d || 1) * sp * dt;
        o.y += (p.y - o.y) / (d || 1) * sp * dt;
      }
      if (d < p.r + o.r + 6) {
        o.dead = true;
        if (o.type === "xp") this.gainXp(o.value);
        if (o.type === "coin") { this.runCoins += o.value; this.save.coins += o.value; UI.toast("+1 coin"); }
        if (o.type === "key") { this.save.keys += 1; UI.toast("+1 chest key"); }
      }
    }
    this.pickups = this.pickups.filter(o => !o.dead);
  }

  gainXp(v) {
    const p = this.player;
    p.xp += v;
    while (p.xp >= p.xpNext) {
      p.xp -= p.xpNext;
      p.level++;
      p.xpNext = Math.floor(p.xpNext * 1.22 + 9);
      this.mode = "level";
      UI.showLevelUp(this);
    }
  }

  applyUpgrade(up) {
    up.apply(this.player);
    this.mode = "playing";
    UI.hideLevelUp();
  }

  skill() {
    const p = this.player;
    if (!p || p.skillTimer > 0) return;
    const skin = this.activeSkinConfig();
    const state = skin.states.skill;
    const duration = state.duration || .4;
    const dir = p.lastDir || "down";
    p.skillTimer = p.skillCooldown;
    p.skillCastTimer = duration;
    p.skillCastDuration = duration;
    p.skillDir = dir;

    if (skin.skillType === "dash") {
      const mv = this.input.getMoveVector();
      const v = Math.hypot(mv.x, mv.y) > .08 ? mv : this.dirVector(dir);
      p.dashDir = v;
      p.dashTimer = skin.dashDuration || duration;
      p.dashSpeed = skin.dashSpeed || 760;
      p.invuln = Math.max(p.invuln || 0, p.dashTimer);
      this.effects.push({ type:"dash", x:p.x, y:p.y, vx:v.x, vy:v.y, t:0, life:.32 });
      for (const e of this.enemies) if (Math.hypot(e.x - p.x, e.y - p.y) < skin.dashDamageRadius) this.damageEnemy(e, p.damage * skin.dashDamageMult);
      return;
    }

    const radius = skin.burstRadius || 185;
    this.effects.push({ type:"burst", x:p.x, y:p.y, r:radius, t:0, life:.45 });
    for (const e of this.enemies) if (Math.hypot(e.x - p.x, e.y - p.y) < radius + e.r) this.damageEnemy(e, p.damage * 3.2);
  }

  gameOver() {
    this.mode = "gameover";
    document.body.classList.remove("is-playing");
    if (this.time > this.save.best.time) this.save.best.time = this.time;
    if (this.kills > this.save.best.kills) this.save.best.kills = this.kills;
    CherriftStorage.save(this.save);
    UI.showGameOver(this);
  }

  render() {
    const c = this.ctx;
    c.clearRect(0, 0, this.w, this.h);
    if (this.mode === "menu") {
      this.drawMenuCanvas(c);
      return;
    }
    if (["playing", "level", "paused", "gameover"].includes(this.mode)) this.drawWorld(c);
  }

  drawMenuCanvas(c) {
    const g = c.createLinearGradient(0, 0, this.w, this.h);
    g.addColorStop(0, "#07030d");
    g.addColorStop(.45, "#1c0b2b");
    g.addColorStop(1, "#06020a");
    c.fillStyle = g;
    c.fillRect(0, 0, this.w, this.h);
  }

  drawWorld(c) {
    c.fillStyle = "#1f7d45";
    c.fillRect(0, 0, this.w, this.h);
    const zoom = CHERRIFT_CONFIG.performance?.cameraZoom || 1;
    c.save();
    c.translate(this.w / 2, this.h / 2);
    c.scale(zoom, zoom);
    c.translate(-this.camera.x, -this.camera.y);
    this.drawGround(c, zoom);
    const drawables = [...this.obstacles, ...this.pickups, ...this.enemies, ...(this.player ? [this.player] : []), ...this.bullets, ...this.effects];
    drawables.sort((a, b) => (a.y || 0) - (b.y || 0));
    for (const o of drawables) this.drawObj(c, o);
    c.restore();
  }

  drawGround(c, zoom = 1) {
    const tile = this.assets.get("grass");
    const size = 128;
    const viewW = this.w / zoom;
    const viewH = this.h / zoom;
    const startX = Math.floor((this.camera.x - viewW / 2) / size) - 1;
    const endX = Math.floor((this.camera.x + viewW / 2) / size) + 1;
    const startY = Math.floor((this.camera.y - viewH / 2) / size) - 1;
    const endY = Math.floor((this.camera.y + viewH / 2) / size) + 1;
    for (let gx=startX; gx<=endX; gx++) for (let gy=startY; gy<=endY; gy++) {
      const x = gx * size, y = gy * size;
      // A one-pixel overlap prevents transparent hairline seams when the
      // dynamic camera lands on fractional device pixels.
      if (tile) c.drawImage(tile, x - .5, y - .5, size + 1, size + 1);
      else {
        c.fillStyle = (gx + gy) % 2 === 0 ? "#2f9d55" : "#2a934f";
        c.fillRect(x, y, size, size);
      }
    }
  }

  drawObj(c, o) {
    if (o === this.player) return this.drawPlayer(c, o);
    if (o.kind) return this.drawObstacle(c, o);
    if (o.type === "xp" || o.type === "coin" || o.type === "key") return this.drawPickup(c, o);
    if (o.style) return this.drawBullet(c, o);
    if (o.hp !== undefined) return this.drawEnemy(c, o);
    if (o.type) return this.drawEffect(c, o);
  }

  drawImageCentered(c, key, x, y, w, h) {
    const img = this.assets.get(key);
    if (!img) return false;
    c.drawImage(img, x - w/2, y - h/2, w, h);
    return true;
  }

  drawObstacle(c, o) {
    const x = o.x, y = o.y;
    if (o.kind === "treeBig" && this.drawImageCentered(c, "treeBig", x, y-16, 190, 190)) return;
    if (o.kind === "treeSmall" && this.drawImageCentered(c, "treeSmall", x, y-12, 150, 150)) return;
    if (o.kind === "bush1" && this.drawImageCentered(c, "bush1", x, y, 116, 98)) return;
    if (o.kind === "bush2" && this.drawImageCentered(c, "bush2", x, y, 118, 100)) return;
    if (o.kind === "log" && this.drawImageCentered(c, "log", x, y, 132, 82)) return;
    if (o.kind === "rockBig" && this.drawImageCentered(c, "rockBig", x, y, 88, 70)) return;
    if (o.kind === "rockSmall" && this.drawImageCentered(c, "rockSmall", x, y, 70, 54)) return;
    if (o.kind === "flowers") {
      c.fillStyle = "#ff9cc8";
      for (let i=0; i<5; i++) { const a = i / 5 * Math.PI * 2; c.beginPath(); c.ellipse(x + Math.cos(a)*8, y + Math.sin(a)*8, 6, 10, a, 0, Math.PI*2); c.fill(); }
      c.fillStyle = "#ffe28a"; c.beginPath(); c.arc(x, y, 5, 0, Math.PI*2); c.fill();
    }
  }

  drawPlayer(c, p) {
    const skin = this.activeSkinConfig();
    const skillActive = (p.skillCastTimer || 0) > 0;
    const dir = skillActive ? (p.skillDir || p.lastDir || "down") : (p.lastDir || "down");
    const stateName = skillActive ? "skill" : (p.moving ? "walk" : "idle");
    const state = skin.states[stateName];
    const img = this.assets.get(`player_${p.skin}_${stateName}_${dir}`);
    if (img) {
      const cfg = CHERRIFT_CONFIG.player;
      const realFrames = Math.max(1, Math.floor(img.width / cfg.frameWidth));
      const frameCount = Math.max(1, Math.min(state.frames || realFrames, realFrames));
      let frame = 0;
      if (stateName === "skill") {
        const elapsed = Math.max(0, (p.skillCastDuration || state.duration || .4) - (p.skillCastTimer || 0));
        frame = Math.min(frameCount - 1, Math.floor(elapsed * (state.fps || 12)));
      } else {
        frame = Math.floor(this.t * (state.fps || 6)) % frameCount;
      }

      const dw = cfg.displayWidth || 116;
      const dh = cfg.displayHeight || 116;
      c.drawImage(
        img,
        frame * cfg.frameWidth, 0,
        cfg.frameWidth, cfg.frameHeight,
        Math.round(p.x - dw / 2),
        Math.round(p.y - dh + 34),
        dw, dh
      );
      return;
    }
    c.fillStyle = "rgba(0,0,0,.25)"; c.beginPath(); c.ellipse(p.x, p.y+24, 28, 10, 0, 0, Math.PI*2); c.fill();
    c.fillStyle = p.skin === "fairy_cherry" ? "#caffdf" : "#ffc1dc"; c.beginPath(); c.arc(p.x, p.y, 24, 0, Math.PI*2); c.fill();
    c.fillStyle = "#ff77b9"; c.beginPath(); c.ellipse(p.x-11, p.y-28, 8, 24, -.35, 0, Math.PI*2); c.ellipse(p.x+11, p.y-28, 8, 24, .35, 0, Math.PI*2); c.fill();
  }

  drawEnemy(c, e) {
    const img = this.assets.get("slime");
    if (img) {
      const cfg = CHERRIFT_CONFIG.slime;
      const frame = Math.floor((this.t + e.phase) * 7) % cfg.columns;
      const row = cfg.rows.move;
      c.save();
      if (e.hit > 0) c.globalAlpha = .65;
      c.drawImage(img, frame * cfg.frameWidth, row * cfg.frameHeight, cfg.frameWidth, cfg.frameHeight, e.x - cfg.displayWidth/2, e.y - cfg.displayHeight/2, cfg.displayWidth, cfg.displayHeight);
      c.restore();
      if (e.type !== "green") {
        c.save();
        c.globalAlpha = e.type === "blue" ? .22 : .25;
        c.fillStyle = e.type === "blue" ? "#4ee4ff" : "#ff66b7";
        c.beginPath(); c.ellipse(e.x, e.y, e.r*1.15, e.r*.82, 0, 0, Math.PI*2); c.fill();
        c.restore();
      }
      return;
    }
    c.fillStyle = e.type === "green" ? "#7ee65e" : e.type === "blue" ? "#62d9ff" : "#ff79bf";
    if (e.hit > 0) c.fillStyle = "#fff";
    c.beginPath(); c.ellipse(e.x, e.y, e.r*1.1, e.r*.82, 0, 0, Math.PI*2); c.fill();
  }

  drawBullet(c, b) {
    c.save(); c.translate(b.x, b.y);
    if (b.style === "petal") { c.fillStyle = "#ff8fc7"; c.rotate(Math.atan2(b.vy, b.vx)); c.beginPath(); c.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); c.fill(); }
    else { c.fillStyle = "#ff65b4"; c.shadowColor = "#ff65b4"; c.shadowBlur = 16; c.beginPath(); c.arc(0, 0, 8, 0, Math.PI*2); c.fill(); }
    c.restore();
  }

  drawPickup(c, o) {
    if (o.type === "xp") { const key = o.value >= 5 ? "xpBig" : "xpSmall"; if (this.drawImageCentered(c, key, o.x, o.y, o.value >= 5 ? 34 : 26, o.value >= 5 ? 34 : 26)) return; }
    c.save(); c.translate(o.x, o.y);
    if (o.type === "xp") { c.fillStyle = "#ff90d0"; c.shadowColor = "#ff90d0"; c.shadowBlur = 14; c.beginPath(); c.arc(0, 0, o.r, 0, Math.PI*2); c.fill(); }
    if (o.type === "coin") { c.fillStyle = "#ffd65c"; c.beginPath(); c.arc(0, 0, 9, 0, Math.PI*2); c.fill(); c.fillStyle = "#9b6a00"; c.fillText("c", -3, 4); }
    if (o.type === "key") { c.fillStyle = "#d19b65"; c.font = "20px system-ui"; c.fillText("📦", -10, 7); }
    c.restore();
  }

  drawEffect(c, e) {
    const a = 1 - e.t / e.life;
    const x = e.x, y = e.y;

    if (e.type === "hit") {
      const img = e.imgKey ? this.assets.get(e.imgKey) : null;
      if (img) {
        c.save();
        c.globalAlpha = Math.max(0, a);
        const size = 74 * (1 + (1 - a) * .18);
        c.drawImage(img, x - size / 2, y - size / 2, size, size);
        c.restore();
        return;
      }
    }

    if (e.type === "burst") {
      const img = this.assets.get("burst");
      if (img) {
        c.save();
        c.globalAlpha = Math.max(0, a);
        const size = 170 * (1.15 - a * .15);
        c.drawImage(img, x - size/2, y - size/2, size, size);
        c.restore();
        return;
      }
    }

    c.save();
    c.globalAlpha = Math.max(0, a);
    if (["hit", "death", "crit", "burst", "dash"].includes(e.type)) {
      c.strokeStyle = e.type === "crit" ? "#fff176" : "#ff8ccc";
      c.lineWidth = e.type === "dash" ? 6 : 4;
      c.beginPath();
      c.arc(x, y, (1-a) * (e.type === "dash" ? 80 : 55) + 8, 0, Math.PI*2);
      c.stroke();
    }
    c.restore();
  }
}
window.CherriftGame = CherriftGame;
/* ===== END src/game.js ===== */


/* ===== BEGIN src/ui.js ===== */
window.UI = {
  skinIndex: 0,
  selectedGear: null,

  init(save, game) {
    this.save = save;
    this.game = game;
    this.skinIndex = Math.max(0, CHERRIFT_DATA.skins.findIndex(s => s.id === save.selectedSkin));
    this.bind();
    this.refreshMenu();
    this.renderSkinCarousel();
    this.renderGear();
  },

  bind() {
    document.getElementById("playBtn").onclick = () => this.game.start();
    document.querySelectorAll("[data-open]").forEach(b => b.onclick = () => this.open(b.dataset.open));
    document.querySelectorAll(".back").forEach(b => b.onclick = () => this.open("menu"));
    document.getElementById("pause").onclick = () => this.pause();
    document.getElementById("resume").onclick = () => this.resume();
    document.getElementById("quit").onclick = () => this.quit();
    document.getElementById("retry").onclick = () => this.game.start();
    document.getElementById("toMenu").onclick = () => this.quit();
    document.getElementById("openChest").onclick = () => this.openChest();
    document.getElementById("skinPrev").onclick = () => { this.skinIndex = (this.skinIndex - 1 + CHERRIFT_DATA.skins.length) % CHERRIFT_DATA.skins.length; this.renderSkinCarousel(); };
    document.getElementById("skinNext").onclick = () => { this.skinIndex = (this.skinIndex + 1) % CHERRIFT_DATA.skins.length; this.renderSkinCarousel(); };
    document.getElementById("skinEquip").onclick = () => {
      const skin = CHERRIFT_DATA.skins[this.skinIndex];
      if (!this.save.unlockedSkins.includes(skin.id)) { this.toast("Skin locked"); return; }
      this.save.selectedSkin = skin.id;
      CherriftStorage.save(this.save);
      this.refreshMenu();
      this.renderSkinCarousel();
      this.toast(`${skin.name} equipped`);
    };
    document.getElementById("fullscreen").onclick = () => this.fullscreen();
    const volume = document.getElementById("volume");
    volume.value = this.save.settings.volume;
    volume.oninput = () => { this.save.settings.volume = +volume.value; CherriftStorage.save(this.save); };
    const touch = document.getElementById("touchMode");
    touch.checked = this.save.settings.touchMode;
    touch.onchange = () => { this.save.settings.touchMode = touch.checked; this.game.input.touchMode = touch.checked; CherriftStorage.save(this.save); };
    this.game.input.touchMode = this.save.settings.touchMode;

    const fpsLimit = document.getElementById("fpsLimit");
    if (fpsLimit) {
      fpsLimit.value = String(this.save.settings.fpsLimit || 60);
      fpsLimit.onchange = () => {
        this.save.settings.fpsLimit = +fpsLimit.value;
        this.game.fpsLimit = this.save.settings.fpsLimit;
        CherriftStorage.save(this.save);
        this.toast(`${this.save.settings.fpsLimit} FPS limit set`);
      };
    }
  },

  open(id) {
    document.body.classList.remove("is-playing");
    ["menu", "skins", "gear", "chests", "settings"].forEach(x => document.getElementById(x).classList.toggle("hidden", x !== id));
    if (id === "menu") this.refreshMenu();
    if (id === "skins") this.renderSkinCarousel();
    if (id === "gear") this.renderGear();
  },

  showGame() {
    ["menu", "skins", "gear", "chests", "settings", "gameOver", "pauseModal", "levelModal"].forEach(x => document.getElementById(x).classList.add("hidden"));
    document.getElementById("hud").classList.remove("hidden");
    document.getElementById("skill").classList.remove("hidden");
    document.body.classList.add("is-playing");
  },

  refreshMenu() {
    document.getElementById("menuCoins").textContent = this.save.coins;
    document.getElementById("menuKeys").textContent = this.save.keys;
    const s = CHERRIFT_DATA.skins.find(x => x.id === this.save.selectedSkin);
    document.getElementById("selectedSkinText").textContent = s ? `${s.emoji} ${s.name}` : "Cherry";
    document.getElementById("bestRun").textContent = `${this.fmt(this.save.best.time)} · ${this.save.best.kills} kills`;
    CherriftStorage.save(this.save);
  },

  renderSkinCarousel() {
    const skin = CHERRIFT_DATA.skins[this.skinIndex];
    const unlocked = this.save.unlockedSkins.includes(skin.id);
    const selected = this.save.selectedSkin === skin.id;
    document.getElementById("skinPortrait").textContent = skin.emoji;
    document.getElementById("skinMini").textContent = skin.emoji;
    document.getElementById("skinRarity").textContent = skin.rarity + (unlocked ? "" : " · LOCKED");
    document.getElementById("skinRarity").className = `rarity-pill rarity-${skin.rarity.toLowerCase()}`;
    document.getElementById("skinName").textContent = skin.name;
    document.getElementById("skinDesc").textContent = skin.desc;
    document.getElementById("skinWeapon").textContent = skin.weapon;
    document.getElementById("skinSkill").textContent = skin.skill;
    document.getElementById("skinSplash").style.background = `radial-gradient(circle at 50% 40%, rgba(255,255,255,.16), transparent 26%), linear-gradient(135deg, ${skin.gradient[0]}, ${skin.gradient[1]})`;
    const btn = document.getElementById("skinEquip");
    btn.textContent = selected ? "EQUIPPED" : unlocked ? "EQUIP" : "LOCKED";
    btn.disabled = !unlocked;
  },

  gearName(g) { return `${g.rarity} ${g.type} ${g.slot}`; },
  gearEmoji(g) { return `${CHERRIFT_DATA.gearTypes[g.type]?.emoji || "⚙"}${CHERRIFT_DATA.slotIcons[g.slot] || ""}`; },

  makeGear() {
    const slots = CHERRIFT_DATA.slots;
    const types = Object.keys(CHERRIFT_DATA.gearTypes);
    const rarityRoll = Math.random();
    const rarity = rarityRoll < .62 ? "Common" : rarityRoll < .90 ? "Uncommon" : "Rare";
    const type = types[Math.floor(Math.random() * types.length)];
    const slot = slots[Math.floor(Math.random() * slots.length)];
    const mult = CHERRIFT_DATA.rarities[rarity].mult;
    const id = "g_" + Date.now() + "_" + Math.random().toString(16).slice(2);
    const stats = {};
    const pool = CHERRIFT_DATA.gearTypes[type].stats;
    const count = rarity === "Rare" ? 3 : rarity === "Uncommon" ? 2 : 1;
    for (let i=0; i<count; i++) {
      const stat = pool[Math.floor(Math.random() * pool.length)];
      const base = { damage:4, crit:3, critDamage:8, attackSpeed:5, maxHp:18, armor:4, regen:.45, moveSpeed:8, pickup:16 }[stat] || 2;
      stats[stat] = (stats[stat] || 0) + Math.round(base * mult * (.75 + Math.random() * .65) * 10) / 10;
    }
    return { id, slot, type, rarity, stats };
  },

  renderGear() {
    const inv = document.getElementById("inventory");

    if (inv) {
      inv.ondragover = e => e.preventDefault();
      inv.ondrop = e => {
        e.preventDefault();
        const slot = e.dataTransfer.getData("slot");
        if (slot) this.unequipGear(slot);
      };
    }

    document.querySelectorAll(".gear-slot").forEach(btn => {
      const slot = btn.dataset.slot;
      const g = this.save.equipped[slot];
      btn.className = `gear-slot ${slot.toLowerCase()} ${g ? "" : "empty"} ${this.selectedGear && this.selectedGear.id === g?.id ? "selected" : ""}`;
      btn.dataset.short = slot.slice(0, 3).toUpperCase();
      btn.innerHTML = g ? `<span>${this.gearEmoji(g)}</span>` : "";
      btn.onclick = () => { if (g) this.showGearDetails(g, "equipped"); else this.showEmptySlot(slot); this.highlightGear(g?.id); };

      btn.draggable = !!g;
      btn.ondragstart = e => {
        if (!g) return;
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("slot", slot);
        e.dataTransfer.setData("gearId", g.id);
        btn.classList.add("dragging");
      };
      btn.ondragend = () => btn.classList.remove("dragging", "drop-target", "bad-drop");
      btn.ondragover = e => {
        e.preventDefault();
        const id = e.dataTransfer.getData("gearId");
        const item = this.save.inventory.find(x => x.id === id);
        btn.classList.toggle("bad-drop", !!item && item.slot !== slot);
        btn.classList.toggle("drop-target", !!item && item.slot === slot);
      };
      btn.ondragleave = () => btn.classList.remove("drop-target", "bad-drop");
      btn.ondrop = e => {
        e.preventDefault();
        btn.classList.remove("drop-target", "bad-drop");
        const id = e.dataTransfer.getData("gearId");
        const item = this.save.inventory.find(x => x.id === id);
        if (!item) return;
        if (item.slot !== slot) {
          this.toast(`${item.slot} item nem rakható ${slot} slotra`);
          return;
        }
        this.equipGear(id);
      };
    });

    inv.innerHTML = "";
    this.save.inventory.forEach(g => {
      const el = document.createElement("button");
      el.className = `inv-item rarity-${g.rarity.toLowerCase()} ${this.selectedGear && this.selectedGear.id === g.id ? "selected" : ""}`;
      el.draggable = true;
      el.dataset.gearId = g.id;
      el.innerHTML = `<span>${this.gearEmoji(g)}</span><small>${g.slot}</small>`;
      el.onclick = () => { this.showGearDetails(g, "inventory"); this.highlightGear(g.id); };
      el.ondragstart = e => {
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("gearId", g.id);
        el.classList.add("dragging");
        this.showGearDetails(g, "inventory");
      };
      el.ondragend = () => el.classList.remove("dragging");
      inv.appendChild(el);
    });

    document.getElementById("inventoryCount").textContent = `${this.save.inventory.length} items`;
    const stats = this.totalGearStats(this.save);
    document.getElementById("totalStats").innerHTML = "<h3>Total Stats</h3>" + (Object.keys(stats).length ? Object.entries(stats).map(([k,v]) => `<div class="stat-line"><span>${k}</span><b>+${Math.round(v*10)/10}</b></div>`).join("") : "<p>No gear equipped.</p>");
  },

  highlightGear(id) { this.renderGear(); },

  showEmptySlot(slot) {
    this.selectedGear = null;
    document.getElementById("gearDetails").innerHTML = `<div class="gear-details-empty"><b>${slot}</b> slot üres.<br>Húzz ide az inventoryból egy ${slot} itemet.</div>`;
  },

  showGearDetails(g, source) {
    this.selectedGear = g;
    const actions = source === "inventory" ? `<button data-action="equip">Equip</button><button data-action="sell">Sell</button>` : `<button data-action="unequip">Unequip</button>`;
    document.getElementById("gearDetails").innerHTML = `
      <div class="gear-detail-title"><div class="gear-detail-icon">${this.gearEmoji(g)}</div><div><h4>${this.gearName(g)}</h4><small class="rarity-${g.rarity.toLowerCase()} type-${g.type.toLowerCase()}">${g.rarity} · ${g.type}</small></div></div>
      <div>${Object.entries(g.stats).map(([k,v]) => `<div class="stat-line"><span>${k}</span><b>+${v}</b></div>`).join("")}</div>
      <div class="gear-detail-actions">${actions}</div>`;
    document.querySelectorAll("#gearDetails [data-action]").forEach(btn => {
      btn.onclick = () => { if (btn.dataset.action === "equip") this.equipGear(g.id); if (btn.dataset.action === "sell") this.sellGear(g.id); if (btn.dataset.action === "unequip") this.unequipGear(g.slot); };
    });
    this.renderGear();
  },

  totalGearStats(save) {
    const out = {};
    Object.values(save.equipped || {}).forEach(g => { if (!g) return; Object.entries(g.stats).forEach(([k,v]) => out[k] = (out[k] || 0) + v); });
    return out;
  },

  equipGear(id) {
    const idx = this.save.inventory.findIndex(g => g.id === id);
    if (idx < 0) return;
    const g = this.save.inventory[idx];
    const old = this.save.equipped[g.slot];
    this.save.inventory.splice(idx, 1);
    if (old) this.save.inventory.push(old);
    this.save.equipped[g.slot] = g;
    CherriftStorage.save(this.save);
    this.selectedGear = g;
    this.renderGear();
    this.showGearDetails(g, "equipped");
  },

  unequipGear(slot) {
    const g = this.save.equipped[slot];
    if (!g) return;
    delete this.save.equipped[slot];
    this.save.inventory.push(g);
    CherriftStorage.save(this.save);
    this.selectedGear = null;
    this.renderGear();
    this.showEmptySlot(slot);
  },

  sellGear(id) {
    const idx = this.save.inventory.findIndex(g => g.id === id);
    if (idx < 0) return;
    const g = this.save.inventory[idx];
    const value = g.rarity === "Rare" ? 15 : g.rarity === "Uncommon" ? 8 : 4;
    this.save.inventory.splice(idx, 1);
    this.save.coins += value;
    CherriftStorage.save(this.save);
    this.toast(`Sold +${value} coins`);
    this.selectedGear = null;
    document.getElementById("gearDetails").innerHTML = `<div class="gear-details-empty">Item sold.</div>`;
    this.renderGear();
    this.refreshMenu();
  },

  openChest() {
    if (this.save.keys <= 0) { this.toast("No keys"); return; }
    this.save.keys--;
    const gear = this.makeGear();
    this.save.inventory.push(gear);
    let extra = "";
    if (Math.random() < .12) {
      const locked = CHERRIFT_DATA.skins.filter(s => !this.save.unlockedSkins.includes(s.id));
      if (locked.length) { const s = locked[Math.floor(Math.random() * locked.length)]; this.save.unlockedSkins.push(s.id); extra = `<br>Unlocked skin: <b>${s.emoji} ${s.name}</b>`; }
    }
    CherriftStorage.save(this.save);
    document.getElementById("chestResult").innerHTML = `Got <b>${this.gearName(gear)}</b><br>${Object.entries(gear.stats).map(([k,v]) => `${k} +${v}`).join(" · ")}${extra}`;
    this.refreshMenu();
    this.renderGear();
  },

  showLevelUp(game) {
    const list = document.getElementById("upgrades");
    list.innerHTML = "";
    const pool = [...CHERRIFT_DATA.upgrades].sort(() => Math.random() - .5).slice(0, 3);
    pool.forEach(up => {
      const btn = document.createElement("button");
      btn.className = "upgrade-card";
      btn.innerHTML = `<strong>${up.name}</strong><span>${up.desc}</span>`;
      btn.onclick = () => game.applyUpgrade(up);
      list.appendChild(btn);
    });
    document.getElementById("levelModal").classList.remove("hidden");
  },

  hideLevelUp() { document.getElementById("levelModal").classList.add("hidden"); },

  updateHUD(game) {
    const p = game.player;
    if (!p) return;
    document.getElementById("hpFill").style.width = `${Math.max(0, p.hp / p.maxHp * 100)}%`;
    document.getElementById("hpText").textContent = `HP ${Math.ceil(Math.max(0, p.hp))}/${Math.ceil(p.maxHp)}`;
    document.getElementById("xpFill").style.width = `${Math.min(100, p.xp / p.xpNext * 100)}%`;
    document.getElementById("xpText").textContent = `LV ${p.level} XP ${p.xp}/${p.xpNext}`;
    document.getElementById("timer").textContent = this.fmt(game.time);
    document.getElementById("kills").textContent = `${game.kills} kills`;
    document.getElementById("runCoins").textContent = game.runCoins;
    const skill = document.getElementById("skill");
    const cd = document.getElementById("cooldown");
    if (p.skillTimer > 0) { skill.classList.add("cooldown"); cd.textContent = p.skillTimer.toFixed(1); } else { skill.classList.remove("cooldown"); cd.textContent = ""; }
  },

  pause() { if (this.game.mode !== "playing") return; this.game.mode = "paused"; document.body.classList.remove("is-playing"); document.getElementById("pauseModal").classList.remove("hidden"); },
  resume() { if (this.game.mode !== "paused") return; this.game.mode = "playing"; document.body.classList.add("is-playing"); document.getElementById("pauseModal").classList.add("hidden"); },
  quit() { this.game.mode = "menu"; document.body.classList.remove("is-playing"); ["hud", "skill", "pauseModal", "gameOver", "levelModal"].forEach(x => document.getElementById(x).classList.add("hidden")); this.open("menu"); },

  showGameOver(game) {
    document.getElementById("gameOver").classList.remove("hidden");
    document.getElementById("runResult").innerHTML = `<p>Time: <b>${this.fmt(game.time)}</b></p><p>Kills: <b>${game.kills}</b></p><p>Coins: <b>${game.runCoins}</b></p>`;
    this.refreshMenu();
  },

  fullscreen() { const el = document.documentElement; if (!document.fullscreenElement && el.requestFullscreen) el.requestFullscreen(); else if (document.exitFullscreen) document.exitFullscreen(); },
  fmt(sec) { sec = Math.floor(sec || 0); const m = Math.floor(sec / 60).toString().padStart(2, "0"); const s = (sec % 60).toString().padStart(2, "0"); return `${m}:${s}`; },
  toast(msg) { const t = document.getElementById("toast"); t.textContent = msg; t.classList.add("show"); clearTimeout(this.toastTimer); this.toastTimer = setTimeout(() => t.classList.remove("show"), 1700); }
};
/* ===== END src/ui.js ===== */


