        const bossMult = e.isBoss ? 1.45 : 1;
        const pulse = 1 + Math.sin(this.t * 6 + (e.phase || 0)) * .018;
        const dw = fc.width * bossMult * pulse;
        const dh = fc.height * bossMult * pulse;
