function directionFromVector(dx, dy) {
  return Math.abs(dx) > Math.abs(dy)
    ? (dx < 0 ? "left" : "right")
    : (dy < 0 ? "up" : "down");
}

function vectorFromDirection(direction) {
  if (direction === "left") return {x:-1, y:0};
  if (direction === "right") return {x:1, y:0};
  if (direction === "up") return {x:0, y:-1};
  return {x:0, y:1};
}

