  return 'radial-gradient(circle at 55% 20%,rgba(255,145,66,.28),transparent 34%),linear-gradient(180deg,rgba(20,8,7,.12),rgba(8,3,7,.82)),url("assets/map/world1/world1_splashart_1.png")';
