/* ========================================================================
 * CLEAN RUNTIME 1.2 — WUXIA DOWN-FRAME + WORLD 2 RGBA ASSET HOTFIX
 * ====================================================================== */
(() => {
"use strict";

const VERSION = "1.2.0-wuxia-world2-rgba";
const SKIN_ID = "wuxia_sakura_cherry";
const FRAME_SIZE = 192;
const CACHE_VERSION = "clean-runtime-1-3";
const VALID_DIRECTIONS = new Set(["down", "up", "left", "right"]);
const FALLBACK_PIVOT = Object.freeze({x:96, y:184});
const stateFrames = Object.freeze({idle:4, walk:6, attack:6, skill:6});
const stateFps = Object.freeze({idle:3, walk:8, attack:18, skill:16});
const fallbackImages = new Map();
const pendingLoads = new Set();

function pathFor(state, direction) {
  return `assets/player/skins/${SKIN_ID}/${SKIN_ID}_${state}_${direction}.png?v=${CACHE_VERSION}`;
}

function keyFor(state, direction) {
  return `player_${SKIN_ID}_${state}_${direction}`;
}

function sanitizeDirection(value) {
  const direction = String(value || "down").toLowerCase();
  return VALID_DIRECTIONS.has(direction) ? direction : "down";
}

function preloadFallbacks() {
  if (typeof Image === "undefined") return;
  for (const state of Object.keys(stateFrames)) {
    for (const direction of VALID_DIRECTIONS) {
      const key = keyFor(state, direction);
      if (fallbackImages.has(key)) continue;
      const image = new Image();
      image.decoding = "async";
      image.onload = () => fallbackImages.set(key, image);
      image.onerror = () => fallbackImages.delete(key);
      image.src = pathFor(state, direction);
      fallbackImages.set(key, image);
    }
  }
}

function validImage(image) {
  return !!image && Math.max(0, Number(image.naturalWidth || image.width) || 0) >= FRAME_SIZE;
}

function requestAsset(game, state, direction) {
  const key = keyFor(state, direction);
  if (!game?.assets?.loadImage || pendingLoads.has(key)) return;
  pendingLoads.add(key);
  game.assets.loadImage(key, pathFor(state, direction))
    .catch(() => false)
    .finally(() => pendingLoads.delete(key));
}

function resolveImage(game, state, direction) {
  const key = keyFor(state, direction);
  const loaded = game?.assets?.get?.(key);
  if (validImage(loaded)) return loaded;
  requestAsset(game, state, direction);

  const preloaded = fallbackImages.get(key);
  if (validImage(preloaded)) return preloaded;

  const idleSameDirection = game?.assets?.get?.(keyFor("idle", direction)) || fallbackImages.get(keyFor("idle", direction));
  if (validImage(idleSameDirection)) return idleSameDirection;

  const idleDown = game?.assets?.get?.(keyFor("idle", "down")) || fallbackImages.get(keyFor("idle", "down"));
  return validImage(idleDown) ? idleDown : null;
}

function patchAssetLoader() {
  if (typeof ImageAssets === "undefined") return;
  const prototype = ImageAssets.prototype;
  if (prototype.__cleanRuntime12WuxiaAssets) return;
  prototype.__cleanRuntime12WuxiaAssets = true;
  const previousLoadAll = prototype.loadAll;
  prototype.loadAll = async function loadAllCleanRuntime12(...args) {
    const result = await previousLoadAll.apply(this, args);
    const jobs = [];
    for (const state of Object.keys(stateFrames)) {
      for (const direction of VALID_DIRECTIONS) {
        const key = keyFor(state, direction);
        if (!validImage(this.get?.(key))) jobs.push(this.loadImage(key, pathFor(state, direction)));
      }
    }
    if (jobs.length) await Promise.all(jobs);
    return result;
  };
}

function currentState(player, config) {
  const skillActive = (player.skillCastTimer || 0) > 0 && config?.states?.skill;
  const attackActive = !skillActive && (player.attackCastTimer || 0) > 0 && config?.states?.attack;
  if (skillActive) return "skill";
  if (attackActive) return "attack";
  return player.moving ? "walk" : "idle";
}

function directionFor(player, state) {
  if (state === "skill") return sanitizeDirection(player.skillDir || player.lastDir);
  if (state === "attack") return sanitizeDirection(player.attackDir || player.lastDir);
  return sanitizeDirection(player.lastDir);
}

function animationFrame(game, player, stateName, stateConfig, image) {
  const realFrames = Math.max(1, Math.floor(Number(image.naturalWidth || image.width) / FRAME_SIZE));
  const frames = Math.max(1, Math.min(Number(stateConfig?.frames || stateFrames[stateName]) || realFrames, realFrames));
  const fps = Number(stateConfig?.fps || stateFps[stateName]) || 6;
  if (stateName === "skill" || stateName === "attack") {
    const timer = stateName === "skill" ? player.skillCastTimer : player.attackCastTimer;
    const duration = stateName === "skill"
      ? player.skillCastDuration || stateConfig?.duration || frames / fps
      : player.attackCastDuration || stateConfig?.duration || frames / fps;
    const elapsed = Math.max(0, Number(duration) - Math.max(0, Number(timer) || 0));
    return Math.min(frames - 1, Math.floor(elapsed * fps));
  }
  return Math.floor((Number(game.t) || 0) * fps) % frames;
}

function drawWuxia(game, context, player) {
  const config = window.CHERRIFT_CONFIG?.player?.skins?.[SKIN_ID] || game.activeSkinConfig?.();
  const stateName = currentState(player, config);
  const direction = directionFor(player, stateName);
  const stateConfig = config?.states?.[stateName] || {};
  const image = resolveImage(game, stateName, direction);
  if (!image) return false;

  const frame = animationFrame(game, player, stateName, stateConfig, image);
  const displayWidth = Math.round((window.CHERRIFT_CONFIG?.player?.displayWidth || 116) * .95);
  const displayHeight = Math.round((window.CHERRIFT_CONFIG?.player?.displayHeight || 116) * .95);
  const pivot = stateConfig.pivot || FALLBACK_PIVOT;
  const destinationX = Math.round(player.x - pivot.x * displayWidth / FRAME_SIZE);
  const destinationY = Math.round(player.y + 30 - pivot.y * displayHeight / FRAME_SIZE);

  context.save();
  context.globalAlpha = .20;
  context.fillStyle = "#000";
  context.beginPath();
  context.ellipse(player.x, player.y + 25, 26, 8, 0, 0, Math.PI * 2);
  context.fill();
  context.restore();

  context.save();
  context.imageSmoothingEnabled = false;
  context.drawImage(
    image,
    frame * FRAME_SIZE,
    0,
    FRAME_SIZE,
    FRAME_SIZE,
    destinationX,
    destinationY,
    displayWidth,
    displayHeight
  );
  context.restore();
  return true;
}

function patchPlayerRenderer() {
  if (!window.CherriftGame) return;
  const prototype = CherriftGame.prototype;
  if (prototype.__cleanRuntime12WuxiaRenderer) return;
  prototype.__cleanRuntime12WuxiaRenderer = true;
  const previousDrawPlayer = prototype.drawPlayer;
  prototype.drawPlayer = function drawPlayerCleanRuntime12(context, player) {
    if (player?.skin !== SKIN_ID) return previousDrawPlayer.call(this, context, player);
    if (drawWuxia(this, context, player)) return;
    // Never draw the old pink debug circle for a temporarily missing Wuxia strip.
    requestAsset(this, "idle", "down");
  };
}

preloadFallbacks();
patchAssetLoader();
patchPlayerRenderer();

window.CHERRIFT_CLEAN_RUNTIME_12 = Object.freeze({
  version:VERSION,
  wuxiaRenderer:true,
  world2RgbaAssets:true,
  cacheVersion:CACHE_VERSION
});
console.info("[CHERRIFT] Clean Runtime 1.2 Wuxia renderer and World 2 RGBA asset hotfix loaded.");
})();

/* ========================================================================
 * CLEAN BOOTSTRAP — replaces the old 54-file dynamic patch loader.
 * ====================================================================== */
window.addEventListener("DOMContentLoaded", async () => {
  const BUILD_TITLE = window.CHERRIFT_BUILD?.title || "CHERRIFT v0.9.3 – TEST BUILD";
  const BUILD_LABEL = window.CHERRIFT_BUILD?.label || "TESZTVERZIÓ · v0.9.3";
  document.title = BUILD_TITLE;
  const bootSub = document.querySelector(".boot-sub-v060");
  if (bootSub) bootSub.textContent = BUILD_LABEL;

  function preferredBootLanguage() {
    try {
      const save = JSON.parse(localStorage.getItem("cherrift_save_v025_polish") || "null");
      if (["hu", "en"].includes(save?.settings?.language)) return save.settings.language;
    } catch (_) {}
    return document.documentElement.lang === "en" ? "en" : "hu";
  }

  function localizedBootMessage(message) {
    const translated = window.CHERRIFT_I18N?.translate?.(message);
    if (translated && translated !== message) return translated;
    if (preferredBootLanguage() !== "hu") return message;
    return {
      "Loading game systems…": "Játékrendszerek betöltése…",
      "Checking account and save…": "Fiók és mentés ellenőrzése…",
      "Loading cloud save…": "Felhőmentés betöltése…",
      "Reading local progress…": "Helyi mentés beolvasása…",
      "Preparing the menu…": "Menü előkészítése…",
      "Finalizing interface…": "Felület véglegesítése…",
      "Loading failed": "A betöltés sikertelen"
    }[message] || message;
  }

  function updateBoot(percent, message) {
    const value = Math.max(3, Math.min(100, Math.round(percent)));
    const fill = document.getElementById("bootFillV060");
    const text = document.getElementById("bootTextV060");
    const label = document.getElementById("bootPercentV060");
    if (fill) fill.style.width = `${value}%`;
    if (text && message) text.textContent = localizedBootMessage(message);
    if (label) label.textContent = `${value}%`;
  }

  function showBootFailure(error) {
    const boot = document.getElementById("bootV060");
    const card = boot?.querySelector(".boot-card-v060");
    const translate = value => {
      const translated = window.CHERRIFT_I18N?.translate?.(value);
      if (translated && translated !== value) return translated;
      if (preferredBootLanguage() !== "hu") return value;
      return {
        "Loading failed": "A betöltés sikertelen",
        "Some game files could not be loaded.": "Néhány játékfájl nem tölthető be.",
        "Reload game": "Játék újratöltése"
      }[value] || value;
    };
    updateBoot(100, translate("Loading failed"));
    document.body.classList.add("v060-booting", "v062-startup-failed");
    boot?.classList.remove("done");
    if (card && !document.getElementById("bootErrorV062")) {
      const details = document.createElement("div");
      details.id = "bootErrorV062";
      details.className = "boot-error-v062";
      details.innerHTML = `<strong>${translate("Loading failed")}</strong><p>${translate("Some game files could not be loaded.")}</p>`;
      const retry = document.createElement("button");
      retry.type = "button";
      retry.className = "boot-retry-v062";
      retry.textContent = translate("Reload game");
      retry.addEventListener("click", () => window.location.reload());
      details.appendChild(retry);
      card.appendChild(details);
    }
    console.error("[CHERRIFT] Clean Runtime startup blocked:", error);
  }

  try {
    updateBoot(38, "Checking account and save…");
    const loadGuestSave = () => CherriftStorage.load();
    const save = window.CHERRIFT_AUTH?.bootstrapSave
      ? await window.CHERRIFT_AUTH.bootstrapSave(loadGuestSave)
      : loadGuestSave();
    updateBoot(44, window.CHERRIFT_AUTH?.getState?.().mode === "discord" ? "Loading cloud save…" : "Reading local progress…");

    if (window.CHERRIFT_V060?.preload) {
      const preloadResult = await window.CHERRIFT_V060.preload(save, (done, total, message) => {
        const ratio = total ? done / total : 0;
        updateBoot(44 + ratio * 49, message);
      });
      if (preloadResult.failures.length) {
        console.warn("[CHERRIFT] Some optional artwork could not be preloaded:", preloadResult.failures);
      }
    }

    updateBoot(95, "Preparing the menu…");
    const input = new CherriftInput();
    const game = new CherriftGame(document.getElementById("game"), input, save);
    UI.init(save, game);
    window.CHERRIFT_V060?.initAfterUI?.(save, game);
    updateBoot(99, "Finalizing interface…");
    window.CHERRIFT_V060?.finishBoot?.();
  } catch (error) {
    showBootFailure(error);
  }
});


